#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int positions[100002];
    int count = 0;

    for (int i = 1; i <= n; i++) {
        int value;
        scanf("%d", &value);
        if (value == 1) {
            positions[++count] = i;
        }
    }

    positions[0] = 0;
    positions[count + 1] = n + 1;

    long long answer = 0;
    for (int i = 1; i <= count; i++) {
        long long left_choices = positions[i] - positions[i - 1];
        long long right_choices = positions[i + 1] - positions[i];
        answer += left_choices * right_choices;
    }

    printf("%lld\n", answer);
    return 0;
}
